using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class StackLogoGlowRepair{static StackLogoGlowRepair(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.isCompiling||!File.Exists("StackLogoGlowRepair.request"))return;File.Delete("StackLogoGlowRepair.request");try{const string d="Assets/Scenes/Oasis/Cafe3DSigns/";var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Cafe.mat");var tex=new Texture2D(2,2);tex.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(mat.GetTexture("_BaseMap"))));Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeStackLogoGlow");int letters=0,burger=0;foreach(string name in new[]{"Stack House raised atlas logo near","Stack House volumetric badge far"}){string path=d+name+".asset";string backup="FinalEnvironmentRoadBackup/BeforeStackLogoGlow/"+name+".asset";if(!File.Exists(backup))File.Copy(path,backup);var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);var before=m.vertices;var tris=m.triangles;var uv=m.uv;var marks=new List<Vector4>();m.GetUVs(3,marks);for(int i=0;i<marks.Count;i++){var q=marks[i];if(q.z!= -2101||q.w!= -6)continue;if(q.x==1&&q.y>.25f&&q.y<.6f&&before[i].y<.6f){q.y=q.y<.36f?3.2f:3.8f;letters++;}else if(before[i].y>.38f&&q.y<1){var color=tex.GetPixelBilinear(uv[i].x,uv[i].y);if(color.maxColorComponent>.3f&&color.grayscale>.10f){q.y=1.65f;burger++;}}marks[i]=q;}m.SetUVs(3,marks);m.UploadMeshData(false);EditorUtility.SetDirty(m);if(!m.vertices.SequenceEqual(before)||!m.triangles.SequenceEqual(tris))throw new Exception("Geometry changed");}UnityEngine.Object.DestroyImmediate(tex);if(ShaderUtil.ShaderHasError(mat.shader))throw new Exception("Shader error");AssetDatabase.SaveAssets();var all=UnityEngine.Object.FindObjectsOfType<MeshRenderer>(true);var logos=all.Where(r=>r.GetComponent<MeshFilter>()&&AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh)==d+"Stack House raised atlas logo near.asset").ToArray();var c=UnityEngine.Object.FindObjectOfType<CityDayNightController>();bool night=c.IsNight;try{c.Apply(true);int n=0;foreach(var r in logos){var b=r.bounds;var pos=b.center+r.transform.forward*27+Vector3.up*1;CityLightingBuilder.Capture(c,Tuple.Create(pos,Quaternion.LookRotation(b.center-pos)),"Stack-Logo-Glow-"+(++n));}}finally{c.Apply(night);}File.WriteAllText("FinalEnvironmentRoadReview/StackLogoGlowRepair.txt","SUCCESS near/far shared logo meshes updated; raised letter vertices="+letters+", burger vertices="+burger+", scene sign instances="+logos.Length+". Existing atlas/material only; poles, dark backs and source geometry unchanged. Night-only glow retained, shader errors=0.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/StackLogoGlowRepair.txt",e.ToString());}}}
